//! 🎚️ Typed fields share original typed equality, authored cloning, and exact inverse ownership.
use crate::{field::RetainedFieldPreparation,retained_mutation_demand_fits};
use semio_framework_value::{RetirementDemand, ValueError, ValueRefusalKind, retained_clone::{RetainedClone, RetainedCloneRef, RetainedCloneGrant, RetainedCloneProgress, RetainedCloneStep}};
use semio_framework_value_persistent::{retained_equality::RetainedEquality, retained_equality::RetainedEqualityOwner};
use std::mem::size_of;
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
fn scalar(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}

/// 🪡️ None means unchanged; Some(value) transfers the original funded authored field without a synthetic source wrapper.
pub struct RetainedFieldChange<T:RetainedEquality+RetainedClone>{equality:RetainedEqualityOwner<T>,authored:RetainedFieldPreparation<T>,original:RetainedFieldPreparation<T>,phase:u8,closing:bool}
impl<T:RetainedEquality+RetainedClone> Default for RetainedFieldChange<T>{fn default()->Self{Self{equality:RetainedEqualityOwner::new(),authored:Default::default(),original:Default::default(),phase:0,closing:false}}}
impl<T:RetainedEquality+RetainedClone> RetainedFieldChange<T>{
 /// ⛽️ Quotes the equality owner, two lazy field preparations and five direct fields.
 pub fn birth_work()->Result<u64,ValueError>{let equality=RetainedEqualityOwner::<T>::birth_work()?;let field=RetainedFieldPreparation::<T>::embedded_birth_work()?;equality.checked_add(field.checked_mul(2).ok_or_else(||invalid("field birth work overflow"))?).and_then(|v|v.checked_add(5)).ok_or_else(||invalid("field birth work overflow"))}
 /// 🧭️ Typed wrappers keep the same original source pair after child ownership transfer.
 pub fn verify_sources(&self,a:RetainedCloneRef<'_,T>,o:RetainedCloneRef<'_,T>)->Result<(),ValueError>{self.equality.verify(a,o)}
 fn fixed()->usize{size_of::<u8>()*2}
 fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=Self::fixed();d.depth+=1;d}
 fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-Self::fixed(),maximum_depth:g.maximum_depth-1,..g}}
 fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_bytes+=Self::fixed();p}
 pub fn ready(&self)->bool{self.phase==2&&!self.closing}
 pub fn inverse_ready(&self)->bool{self.phase==4&&!self.closing}
 pub fn decision_demand(&self,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid("typed field decision is closing"))}Ok(match self.phase{0=>Self::nested(self.equality.demand(body.saturating_sub(Self::fixed()),maximum_work_units.saturating_sub(2))?),1=>Self::nested(self.authored.demand(body.saturating_sub(Self::fixed()),maximum_work_units.saturating_sub(2))?),2=>self.change_demand()?,_=>return Err(invalid("typed field decision is spent"))})}
 pub fn decision_work_demand(&self,body:usize,maximum_work_units:u64)->Result<u64,ValueError>{self.decision_demand(body,maximum_work_units)?;if maximum_work_units==0||self.phase==2{return Ok(0)}let child=match self.phase{0=>self.equality.work_demand(body.saturating_sub(Self::fixed()),maximum_work_units.saturating_sub(2))?,1=>self.authored.advance_work_demand(body.saturating_sub(Self::fixed()),maximum_work_units.saturating_sub(2))?,_=>return Err(invalid("typed field decision is spent"))};if child==0{return Ok(0)}let work=child.checked_add(2).ok_or_else(||invalid("typed field work overflow"))?;Ok(if work<=maximum_work_units{work}else{0})}
 pub fn decide(&mut self,authored:RetainedCloneRef<'_,T>,original:RetainedCloneRef<'_,T>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant,actual:&mut Option<usize>)->semio_framework_value::OriginalRetirementOutcome{let mut work=0;let result:Result<_,semio_framework_value::OriginalRetirementFailure>=(||{if actual.is_some(){return Err(invalid("field decision needs an empty allocation marker").into())}if self.ready(){return Ok(RetainedCloneStep::Complete(Default::default()))}if self.decision_work_demand(body,maximum_work_units)?==0{return Ok(RetainedCloneStep::Progress(Default::default()))}let d=self.decision_demand(body,maximum_work_units)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let p=match self.phase{0=>{let turn=self.equality.advance(authored,original,body.saturating_sub(Self::fixed()),maximum_work_units-2,Self::child(g),actual);work=1+turn.work;let step=turn.result?;let mut progress=step.progress;if step.equal.is_some(){self.phase=if self.equality.result()==Some(true){2}else{1};work+=1;progress.copied_items=1;progress.copied_bytes+=Self::fixed();}progress},1=>{let turn=self.authored.advance(authored,body.saturating_sub(Self::fixed()),maximum_work_units-2,Self::child(g),actual);work=1+turn.work;let step=turn.result?;let complete=matches!(step,RetainedCloneStep::Complete(_));let mut progress=step.progress();if complete{self.phase=2;work+=1;progress.copied_items=1;progress.copied_bytes+=Self::fixed();}progress},_=>return Err(invalid("typed field decision is spent").into())};Ok(if self.ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})})();semio_framework_value::RetainedWorkOutcome{result,work}}
 /// 📤️ Quotes both the original authored child transfer and the exact outer tri-state result header.
 pub fn change_demand(&self)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(invalid("typed field authored change is not ready"));}let fixed=size_of::<Option<T>>()*2+Self::fixed();if self.equality.result()==Some(true){return Ok(scalar(fixed));}let mut d=self.authored.exchange_demand()?;d.copy_bytes+=fixed;d.depth+=1;Ok(d)}
 pub fn take_change_work_demand(&self)->Result<u64,ValueError>{self.change_demand()?;Ok(1)}
 pub fn take_change(&mut self,g:RetainedCloneGrant)->semio_framework_value::RetainedWorkOutcome<Option<(Option<T>,RetainedCloneProgress)>,ValueError>{let mut work=0;let result=(||{let d=self.change_demand()?;if !retained_mutation_demand_fits(d,g){return Ok(None);}let fixed=size_of::<Option<T>>()*2+Self::fixed();let(value,progress)=if self.equality.result()==Some(true){(None,RetainedCloneProgress{copied_items:1,copied_bytes:fixed,..Default::default()})}else{let(value,mut p)=self.authored.take(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-fixed,maximum_depth:g.maximum_depth-1,..g})?;p.copied_bytes+=fixed;(Some(value.ok_or_else(||invalid("typed field authored field disappeared"))?),p)};self.phase=3;work=1;Ok(Some((value,progress)))})();semio_framework_value::RetainedWorkOutcome{result,work}}
 pub fn inverse_demand(&self,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing||self.phase!=3{return Err(invalid("typed field inverse lacks original decision transfer"))}Ok(Self::nested(self.original.demand(body.saturating_sub(Self::fixed()),maximum_work_units.saturating_sub(self.equality.verify_original_work().saturating_add(1)))?))}
 pub fn inverse_work_demand(&self,body:usize,maximum_work_units:u64)->Result<u64,ValueError>{self.inverse_demand(body,maximum_work_units)?;let child=self.original.advance_work_demand(body.saturating_sub(Self::fixed()),maximum_work_units.saturating_sub(self.equality.verify_original_work().saturating_add(1)))?;if child==0{return Ok(0)}let work=child.checked_add(self.equality.verify_original_work()).and_then(|v|v.checked_add(1)).ok_or_else(||invalid("typed field inverse work overflow"))?;Ok(if work<=maximum_work_units{work}else{0})}
 pub fn inverse(&mut self,original:RetainedCloneRef<'_,T>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant,actual:&mut Option<usize>)->semio_framework_value::OriginalRetirementOutcome{let mut work=0;let result:Result<_,semio_framework_value::OriginalRetirementFailure>=(||{if actual.is_some(){return Err(invalid("field inverse needs an empty allocation marker").into())}if self.inverse_work_demand(body,maximum_work_units)?==0{return Ok(RetainedCloneStep::Progress(Default::default()))}let d=self.inverse_demand(body,maximum_work_units)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let checked=self.equality.verify_original_paid(original,maximum_work_units,g);work=checked.work;if checked.result?!=Some(true){return Err(invalid("field original binding changed").into())}let overhead=self.equality.verify_original_work().checked_add(1).ok_or_else(||invalid("field inverse work overflow"))?;let turn=self.original.advance(original,body.saturating_sub(Self::fixed()),maximum_work_units-overhead,Self::child(g),actual);work+=turn.work;let step=turn.result?;let complete=matches!(step,RetainedCloneStep::Complete(_));let mut progress=step.progress();if complete{self.phase=4;work+=1;progress.copied_items=1;progress.copied_bytes+=Self::fixed();}Ok(if complete{RetainedCloneStep::Complete(progress)}else{RetainedCloneStep::Progress(progress)})})();semio_framework_value::RetainedWorkOutcome{result,work}}
 pub fn inverse_take_demand(&self)->Result<RetirementDemand,ValueError>{if self.phase!=4||self.closing{return Err(invalid("typed field inverse is not ready"));}Ok(Self::nested(self.original.exchange_demand()?))}
 pub fn take_inverse_work_demand(&self)->Result<u64,ValueError>{self.inverse_take_demand()?;Ok(1)}
 pub fn take_inverse(&mut self,g:RetainedCloneGrant)->semio_framework_value::RetainedWorkOutcome<Option<(T,RetainedCloneProgress)>,ValueError>{let mut work=0;let result=(||{let d=self.inverse_take_demand()?;if !retained_mutation_demand_fits(d,g){return Ok(None);}let(value,p)=self.original.take(Self::child(g))?;self.phase=5;work=1;Ok(Some((value.ok_or_else(||invalid("typed field original inverse disappeared"))?,Self::receipt(p))))})();semio_framework_value::RetainedWorkOutcome{result,work}}
 pub fn begin_close(&mut self){self.closing=true;self.authored.begin_close();self.original.begin_close();self.equality.begin_close();}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid("typed field field close has not begun"));}let body=body.saturating_sub(Self::fixed());Ok(Self::nested(if !self.authored.terminal_is_empty(){self.authored.close_demand(body)?}else if !self.original.terminal_is_empty(){self.original.close_demand(body)?}else{self.equality.close_demand(body)?}))}
 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{self.close_demand(body)?;let body=body.saturating_sub(Self::fixed());let child=if !self.authored.terminal_is_empty(){self.authored.close_work_demand(body)?}else if !self.original.terminal_is_empty(){self.original.close_work_demand(body)?}else{self.equality.close_work_demand(body)?};if child==0{return Ok(0)}child.checked_add(1).ok_or_else(||invalid("typed field close work overflow"))}
 pub fn close_step(&mut self,g:RetainedCloneGrant,actual:&mut Option<usize>)->semio_framework_value::OriginalRetirementOutcome{let mut work=0;let result:Result<_,semio_framework_value::OriginalRetirementFailure>=(||{let d=self.close_demand(g.maximum_copy_bytes)?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let turn=if !self.authored.terminal_is_empty(){self.authored.close_step(Self::child(g),actual)}else if !self.original.terminal_is_empty(){self.original.close_step(Self::child(g),actual)}else{self.equality.close_step(Self::child(g))};work=1+turn.work;let step=turn.result?;let p=step.progress();Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})})();semio_framework_value::RetainedWorkOutcome{result,work}}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.authored.terminal_is_empty()&&self.original.terminal_is_empty()&&self.equality.terminal_is_empty()}
}

